(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('pomodoro-timer-plugin', {
    meta: {
      name: 'Pomodoro Timer Plugin',
      type: 'Plugin',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Full-featured Pomodoro timer with card association and statistics'
    },

    STORAGE_KEY: 'pomodoro-timer-data',
    widget: null,
    timer: null,
    state: {
      isRunning: false,
      isPaused: false,
      currentCard: null,
      timeRemaining: 25 * 60, // 25 minutes in seconds
      sessionType: 'work', // 'work', 'short-break', 'long-break'
      completedSessions: 0,
      stats: {}
    },

    onAppInit(ctx) {
      this.loadState();
      this.createWidget(ctx);
      this.addKeyboardShortcut(ctx);
      ctx.logger.log('Pomodoro Timer initialized');
    },

    loadState() {
      try {
        const saved = localStorage.getItem(this.STORAGE_KEY);
        if (saved) {
          const data = JSON.parse(saved);
          this.state.stats = data.stats || {};
        }
      } catch (err) {
        console.error('Failed to load Pomodoro state:', err);
      }
    },

    saveState() {
      try {
        localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
          stats: this.state.stats
        }));
      } catch (err) {
        console.error('Failed to save Pomodoro state:', err);
      }
    },

    createWidget(ctx) {
      this.widget = document.createElement('div');
      this.widget.id = 'pomodoro-widget';
      this.widget.innerHTML = `
        <div class="pomodoro-header">
          <span class="pomodoro-icon">🍅</span>
          <span class="pomodoro-title">Pomodoro</span>
          <button class="pomodoro-minimize" title="Minimize">−</button>
        </div>
        <div class="pomodoro-body">
          <div class="pomodoro-timer">25:00</div>
          <div class="pomodoro-session-type">Work Session</div>
          <div class="pomodoro-card-name">No card selected</div>
          <div class="pomodoro-controls">
            <button class="pomodoro-start">Start</button>
            <button class="pomodoro-pause" disabled>Pause</button>
            <button class="pomodoro-reset">Reset</button>
          </div>
          <div class="pomodoro-stats">
            <div>Sessions: <span class="pomodoro-sessions-count">0</span></div>
            <div>Today: <span class="pomodoro-today-count">0</span></div>
          </div>
          <div class="pomodoro-settings">
            <label>
              <input type="checkbox" class="pomodoro-auto-break"> Auto-start breaks
            </label>
          </div>
        </div>
      `;

      document.body.appendChild(this.widget);
      this.attachEventListeners(ctx);
      this.updateDisplay();
    },

    attachEventListeners(ctx) {
      const startBtn = this.widget.querySelector('.pomodoro-start');
      const pauseBtn = this.widget.querySelector('.pomodoro-pause');
      const resetBtn = this.widget.querySelector('.pomodoro-reset');
      const minimizeBtn = this.widget.querySelector('.pomodoro-minimize');

      startBtn.addEventListener('click', () => this.start(ctx));
      pauseBtn.addEventListener('click', () => this.pause(ctx));
      resetBtn.addEventListener('click', () => this.reset(ctx));
      minimizeBtn.addEventListener('click', () => this.toggleMinimize());
    },

    addKeyboardShortcut(ctx) {
      this.keyHandler = (e) => {
        if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'P') {
          e.preventDefault();
          this.toggleMinimize();
        }
      };
      document.addEventListener('keydown', this.keyHandler);
    },

    start(ctx) {
      if (!this.state.isRunning) {
        this.state.isRunning = true;
        this.state.isPaused = false;

        // Get current card
        const currentCardId = this.getCurrentCardId();
        if (currentCardId) {
          this.state.currentCard = currentCardId;
        }

        this.timer = setInterval(() => this.tick(ctx), 1000);
        this.updateDisplay();
        ctx.utils.showToast('Pomodoro started', 'success');
      } else if (this.state.isPaused) {
        this.state.isPaused = false;
        this.updateDisplay();
      }
    },

    pause(ctx) {
      this.state.isPaused = true;
      this.updateDisplay();
      ctx.utils.showToast('Pomodoro paused', 'info');
    },

    reset(ctx) {
      this.stop();
      this.state.timeRemaining = this.getDuration(this.state.sessionType);
      this.updateDisplay();
      ctx.utils.showToast('Pomodoro reset', 'info');
    },

    stop() {
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
      this.state.isRunning = false;
      this.state.isPaused = false;
    },

    tick(ctx) {
      if (this.state.isPaused) return;

      this.state.timeRemaining--;
      this.updateDisplay();

      if (this.state.timeRemaining <= 0) {
        this.sessionComplete(ctx);
      }
    },

    sessionComplete(ctx) {
      this.stop();

      // Record session
      if (this.state.sessionType === 'work') {
        this.state.completedSessions++;
        this.recordSession();
        ctx.utils.showToast('Work session complete! Take a break.', 'success');

        // Next session type
        if (this.state.completedSessions % 4 === 0) {
          this.state.sessionType = 'long-break';
        } else {
          this.state.sessionType = 'short-break';
        }
      } else {
        ctx.utils.showToast('Break complete! Ready for work.', 'success');
        this.state.sessionType = 'work';
      }

      this.state.timeRemaining = this.getDuration(this.state.sessionType);

      // Auto-start if enabled
      const autoBreak = this.widget.querySelector('.pomodoro-auto-break');
      if (autoBreak && autoBreak.checked) {
        setTimeout(() => this.start(ctx), 2000);
      }

      this.updateDisplay();

      // Play notification sound (if browser supports)
      this.playNotificationSound();
    },

    getDuration(sessionType) {
      switch (sessionType) {
        case 'work': return 25 * 60;
        case 'short-break': return 5 * 60;
        case 'long-break': return 15 * 60;
        default: return 25 * 60;
      }
    },

    recordSession() {
      const today = new Date().toISOString().split('T')[0];

      if (!this.state.stats[today]) {
        this.state.stats[today] = { count: 0, cards: {} };
      }

      this.state.stats[today].count++;

      if (this.state.currentCard) {
        if (!this.state.stats[today].cards[this.state.currentCard]) {
          this.state.stats[today].cards[this.state.currentCard] = 0;
        }
        this.state.stats[today].cards[this.state.currentCard]++;
      }

      this.saveState();
    },

    getCurrentCardId() {
      // Try to get current card from URL or UI
      const params = new URLSearchParams(window.location.search);
      return params.get('card') || null;
    },

    getTodayStats() {
      const today = new Date().toISOString().split('T')[0];
      return this.state.stats[today]?.count || 0;
    },

    updateDisplay() {
      if (!this.widget) return;

      // Update timer display
      const minutes = Math.floor(this.state.timeRemaining / 60);
      const seconds = this.state.timeRemaining % 60;
      const timerDisplay = this.widget.querySelector('.pomodoro-timer');
      timerDisplay.textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;

      // Update session type
      const sessionTypeDisplay = this.widget.querySelector('.pomodoro-session-type');
      const sessionNames = {
        'work': 'Work Session',
        'short-break': 'Short Break',
        'long-break': 'Long Break'
      };
      sessionTypeDisplay.textContent = sessionNames[this.state.sessionType];

      // Update buttons
      const startBtn = this.widget.querySelector('.pomodoro-start');
      const pauseBtn = this.widget.querySelector('.pomodoro-pause');

      if (this.state.isRunning) {
        startBtn.disabled = true;
        pauseBtn.disabled = false;
      } else {
        startBtn.disabled = false;
        pauseBtn.disabled = true;
      }

      // Update stats
      this.widget.querySelector('.pomodoro-sessions-count').textContent = this.state.completedSessions;
      this.widget.querySelector('.pomodoro-today-count').textContent = this.getTodayStats();

      // Update widget class
      this.widget.classList.toggle('pomodoro-running', this.state.isRunning);
      this.widget.classList.toggle('pomodoro-paused', this.state.isPaused);
    },

    toggleMinimize() {
      this.widget.classList.toggle('minimized');
    },

    playNotificationSound() {
      // Create a simple beep using Web Audio API
      try {
        const audioContext = new (window.AudioContext || window.webkitAudioContext)();
        const oscillator = audioContext.createOscillator();
        const gainNode = audioContext.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(audioContext.destination);

        oscillator.frequency.value = 800;
        gainNode.gain.value = 0.3;

        oscillator.start();
        oscillator.stop(audioContext.currentTime + 0.2);
      } catch (err) {
        // Silent fail if audio not supported
      }
    },

    onNavigate(ctx, navigationInfo) {
      // Update current card when navigating
      if (navigationInfo.cardId) {
        this.state.currentCard = navigationInfo.cardId;
        const cardName = this.widget.querySelector('.pomodoro-card-name');
        if (cardName) {
          cardName.textContent = navigationInfo.cardTitle || 'Card selected';
        }
      }
    },

    onDisable(ctx) {
      this.stop();
      if (this.widget && this.widget.parentNode) {
        this.widget.parentNode.removeChild(this.widget);
      }
      if (this.keyHandler) {
        document.removeEventListener('keydown', this.keyHandler);
      }
    },

    onUninstall(ctx) {
      if (confirm('Remove all Pomodoro statistics?')) {
        localStorage.removeItem(this.STORAGE_KEY);
      }
    }
  });
})();

