#pomodoro-widget {
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 280px;
  background: var(--bg-alt);
  border: 2px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
  z-index: 10000;
  transition: all 0.3s;
}

#pomodoro-widget.minimized {
  width: auto;
}

#pomodoro-widget.minimized .pomodoro-body {
  display: none;
}

.pomodoro-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px;
  background: var(--accent);
  color: white;
  border-radius: 10px 10px 0 0;
  cursor: move;
}

.pomodoro-icon {
  font-size: 1.2em;
}

.pomodoro-title {
  flex: 1;
  font-weight: bold;
}

.pomodoro-minimize {
  background: rgba(255, 255, 255, 0.2);
  border: none;
  color: white;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1.2em;
  line-height: 1;
}

.pomodoro-minimize:hover {
  background: rgba(255, 255, 255, 0.3);
}

.pomodoro-body {
  padding: 16px;
}

.pomodoro-timer {
  font-size: 2.5em;
  font-weight: bold;
  text-align: center;
  color: var(--accent);
  margin: 16px 0;
  font-family: 'Courier New', monospace;
}

#pomodoro-widget.pomodoro-running .pomodoro-timer {
  color: #4caf50;
}

#pomodoro-widget.pomodoro-paused .pomodoro-timer {
  color: #ff9800;
}

.pomodoro-session-type {
  text-align: center;
  font-weight: bold;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.pomodoro-card-name {
  text-align: center;
  font-size: 0.85em;
  color: var(--text-secondary);
  margin-bottom: 16px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pomodoro-controls {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.pomodoro-controls button {
  flex: 1;
  padding: 8px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s;
}

.pomodoro-controls button:hover:not(:disabled) {
  background: var(--accent);
  color: white;
  border-color: var(--accent);
}

.pomodoro-controls button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.pomodoro-stats {
  display: flex;
  justify-content: space-around;
  padding: 12px;
  background: var(--bg-hover);
  border-radius: 6px;
  margin-bottom: 12px;
  font-size: 0.9em;
}

.pomodoro-stats span {
  font-weight: bold;
  color: var(--accent);
}

.pomodoro-settings {
  font-size: 0.85em;
}

.pomodoro-settings label {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.pomodoro-settings input[type="checkbox"] {
  cursor: pointer;
}

/* Draggable widget */
#pomodoro-widget {
  user-select: none;
}

#pomodoro-widget.pomodoro-running {
  border-color: #4caf50;
  box-shadow: 0 4px 20px rgba(76, 175, 80, 0.3);
}
